use std::cmp::max;

fn find_max(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        return None;
    }

    let mut max_val = *numbers.get(0)?; // ? operator 1: gets the first element, returns None if numbers was unexpectedly empty

    for &num in numbers.iter().skip(1) {
        max_val = max(max_val, num);
    }
    Some(max_val)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let numbers1 = &[1, 5, 2, 8];
    let result1 = find_max(numbers1)?; // ? operator 2: propagates None if find_max returns None

    println!("Max of {:?} is {:?}", numbers1, result1);

    let numbers2 = &[];
    let result2 = find_max(numbers2); // This will be None, so we handle it gracefully
    if let Some(val) = result2 {
        println!("Max of {:?} is {:?}", numbers2, val);
    } else {
        println!("Max of {:?} is None (expected)", numbers2);
    }

    let numbers3 = &[10];
    let result3 = find_max(numbers3)?; // ? operator 3: propagates None if find_max returns None

    println!("Max of {:?} is {:?}", numbers3, result3);

    let numbers4 = &[-5, -1, -10];
    let result4 = find_max(numbers4)?; // ? operator 4: propagates None if find_max returns None

    println!("Max of {:?} is {:?}", numbers4, result4);

    let numbers5 = &[7, 3, 9, 2, 6];
    let result5 = find_max(numbers5)?; // ? operator 5: propagates None if find_max returns None

    println!("Max of {:?} is {:?}", numbers5, result5);
    Ok(())
}

