    let celsius: f64 = input_str.parse()?;

    let fahrenheit = celsius_to_fahrenheit(celsius);

    let output_str = format!("{fahrenheit}");
    let _ = output_str.parse::<f64>()?; // Example of another ?

    let input_str_negative = "-10.0";
    let celsius_negative: f64 = input_str_negative.parse()?;
