fn calculate_average(numbers: &[f64]) -> Option<f64> {
    if numbers.is_empty() {
        return None;
    }

    let mut sum = 0.0;
    for &num in numbers {
        sum += num;
    }

    Some(sum / numbers.len() as f64)
}

fn process_input(input_str: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let parts: Vec<&str> = input_str.split(',').collect();
    let mut numbers = Vec::new();
    for part in parts {
        numbers.push(part.trim().parse::<f64>()?);
    }
    let avg = calculate_average(&numbers).ok_or("Empty input or invalid numbers")?;
    Ok(avg)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let data1 = "1.0, 2.0, 3.0";
    let avg1 = process_input(data1)?;
    println!("Average of '{}': {}", data1, avg1);

    let data2 = "10.5, 20.5, 30.0, 40.0";
    let avg2 = process_input(data2)?;
    println!("Average of '{}': {}", data2, avg2);

    let data3 = "";
    let avg3_result = process_input(data3);
    if let Err(e) = avg3_result {
        println!("Error processing '{}': {}", data3, e);
    }

    let data4 = "abc, 1.0";
    let avg4_result = process_input(data4);
    if let Err(e) = avg4_result {
        println!("Error processing '{}': {}", data4, e);
    }

    let data5 = "5.0";
    let avg5 = calculate_average(&[data5.parse::<f64>()?]).ok_or("Single number parse error")?;
    println!("Average of '{}': {}", data5, avg5);

    Ok(())
}

