use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct CapitalizationError;

impl fmt::Display for CapitalizationError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Failed to capitalize string")
    }
}

impl Error for CapitalizationError {}

fn capitalize_first(s: &str) -> Result<String, Box<dyn Error>> {
    if s.is_empty() {
        return Ok(String::new());
    }

    let mut chars = s.chars();
    let first_char = chars.next()
        .ok_or_else(|| Box::new(CapitalizationError) as Box<dyn Error>)?
        .to_uppercase()
        .to_string();

    let remaining = chars.collect::<String>().to_lowercase();
    let mut result = String::with_capacity(first_char.len() + remaining.len());
    result.push_str(&first_char);
    result.push_str(&remaining);
    Ok(result)
}

fn main() -> Result<(), Box<dyn Error>> {
    let s1 = "hello";
    let capitalized_s1 = capitalize_first(s1)?;
    println!("'{}' -> '{}'", s1, capitalized_s1);

    let s2 = "world";
    let capitalized_s2 = capitalize_first(s2)?;
    println!("'{}' -> '{}'", s2, capitalized_s2);

    let s3 = "";
    let capitalized_s3 = capitalize_first(s3)?;
    println!("'{}' -> '{}'", s3, capitalized_s3);

    let s4 = "rust programming";
    let capitalized_s4 = capitalize_first(s4)?;
    println!("'{}' -> '{}'", s4, capitalized_s4);

    let s5 = "a";
    let capitalized_s5 = capitalize_first(s5)?;
    println!("'{}' -> '{}'", s5, capitalized_s5);

    Ok(())
}

