use std::io::{self, BufRead};

fn dot_product(v1: &[f64], v2: &[f64]) -> io::Result<f64> {
    if v1.len() != v2.len() || v1.is_empty() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Vectors must be non-empty and of equal length"));
    }

    let mut sum = 0.0;
    for i in 0..v1.len() {
        let val1 = *v1.get(i).ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Failed to get element from v1"))?;
        let val2 = *v2.get(i).ok_or_else(|| io::Error::new(io::ErrorKind::Other, "Failed to get element from v2"))?;
        sum += val1 * val2;
    }
    Ok(sum)
}

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let v1_str = lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "Missing v1 input"))??;
    let v2_str = lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "Missing v2 input"))??;

    let v1: Vec<f64> = v1_str.split_whitespace()
        .map(|s| s.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<Result<_, _>>()?;

    let v2: Vec<f64> = v2_str.split_whitespace()
        .map(|s| s.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<Result<_, _>>()?;

    let result = dot_product(&v1, &v2)?;
    println!("{}", result);
    Ok(())
}

