    let v1_str = match v1_str { Ok(v) => v, Err(e) => return Err(e.into()), };
    let v2_str = match lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "Missing v2 input")) { Ok(v) => v, Err(e) => return Err(e.into()), };
    let v2_str = match v2_str { Ok(v) => v, Err(e) => return Err(e.into()), };

    let v1: Vec<f64> = match v1_str.split_whitespace()
        .map(|s| s.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<Result<_, _>>() { Ok(v) => v, Err(e) => return Err(e.into()), };

    let v2: Vec<f64> = match v2_str.split_whitespace()
        .map(|s| s.parse().map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)))
        .collect::<Result<_, _>>() { Ok(v) => v, Err(e) => return Err(e.into()), };

    let result = match dot_product(&v1, &v2) { Ok(v) => v, Err(e) => return Err(e.into()), };
    println!("{}", result);
    Ok(())
}

