fn count_word_occurrences(text: &str, word: &str) -> Result<usize, io::Error> {
    let lower_word = word.to_lowercase();
    let mut count = 0;

    let reader = io::Cursor::new(text.as_bytes());
    for line_result in reader.lines() {
        let line = line_result?;
        for text_word_candidate in line.split(|c: char| !c.is_alphanumeric()) {
            if text_word_candidate.is_empty() { continue; }
            if text_word_candidate.to_lowercase() == lower_word {
                count += 1;
