fn simple_interest(principal: f64, rate: f64, time: f64) -> Result<f64, String> {
    let interest = principal * rate * time;
    let total_amount = principal + interest;
    Ok(total_amount)
}

fn calculate_and_display(p_str: &str, r_str: &str, t_str: &str) -> Result<String, String> {
    let principal = p_str.parse::<f64>().map_err(|e| e.to_string())?;
    let rate = r_str.parse::<f64>().map_err(|e| e.to_string())?;
    let time = t_str.parse::<f64>().map_err(|e| e.to_string())?;

    if principal < 0.0 {
        return Err("Principal cannot be negative".to_string());
    }
    if rate < 0.0 {
        return Err("Rate cannot be negative".to_string());
    }
    if time < 0.0 {
        return Err("Time cannot be negative".to_string());
    }

    let result = simple_interest(principal, rate, time)?;
    Ok(format!("Total amount: {:.2}", result))
}

fn main() -> Result<(), String> {
    let amount1 = calculate_and_display("1000.0", "0.05", "2.0")?;
    println!("{}", amount1);

    let amount2 = calculate_and_display("500.0", "0.10", "1.0")?;
    println!("{}", amount2);

    let invalid_principal = calculate_and_display("-100.0", "0.05", "1.0");
    if let Err(e) = invalid_principal {
        println!("Error: {}", e);
    }

    let invalid_rate_parse = calculate_and_display("1000.0", "abc", "2.0");
    if let Err(e) = invalid_rate_parse {
        println!("Error: {}", e);
    }
    Ok(())
}

