fn check_guess(target: u32, guess: u32) -> &'static str {
    if guess < target {
        "Too low"
    } else if guess > target {
        "Too high"
    } else {
        "Correct"
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let target = 42;

    println!("Guess a number between 1 and 100:");
    let mut guess_str = String::new();
    std::io::stdin().read_line(&mut guess_str)?;

    let guess: u32 = guess_str.trim().parse()?;

    let result = check_guess(target, guess);
    println!("Your guess was: {}", result);

    if result == "Correct" {
        println!("Congratulations, you guessed it!");
    } else {
        println!("Better luck next time!");
    }

    // Example of another potential ? operator usage, though not directly related to the guess logic
    let temp_file_path = std::env::temp_dir().join("guess_log.txt");
    std::fs::write(&temp_file_path, format!("Target: {}, Guess: {}, Result: {}\n", target, guess, result))?;
    println!("Logged result to: {:?}", temp_file_path);

    let content = std::fs::read_to_string(&temp_file_path)?;
    println!("Log content:\n{}", content);

    let _ = std::fs::remove_file(&temp_file_path)?; // Clean up, ignoring error if file already gone

    Ok(())
}

