use std::error::Error;

fn parse_csv_line(line: &str) -> Result<Vec<String>, Box<dyn Error>> {
    let mut fields = Vec::new();
    let parts = line.split(',');

    for part in parts {
        let trimmed_part = part.trim();
        if trimmed_part.is_empty() && part.len() > 0 { // Check if original part was just whitespace
            return Err("Empty field value".into());
        }
        fields.push(trimmed_part.to_string());
    }

    // Example of using ? with a custom error for a specific condition
    if line.is_empty() {
        return Err("Input line cannot be empty".into());
    }

    Ok(fields)
}

// Helper function to simulate another operation that might fail
fn process_and_validate(data: &str) -> Result<String, Box<dyn Error>> {
    let parsed_fields = match parse_csv_line(data) { // First ?
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let first_field = match parsed_fields.get(0)
        .ok_or_else(|| "No fields found".to_string()) { // Second ?
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let len_check = first_field.len();
    if len_check < 1 {
        return Err("First field too short".into());
    }

    // Simulate another fallible operation, e.g., converting to integer
    let numeric_part = match first_field.parse::<u32>()
        .map_err(|e| e.to_string()) { // Third ?
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    if numeric_part == 0 {
        return Err("Numeric part cannot be zero".into());
    }

    let final_result = format!("Processed: {}", numeric_part);

    Ok(final_result)
}

// Another helper to demonstrate more ? usage
fn analyze_data(input: &str) -> Result<usize, Box<dyn Error>> {
    let processed_string = match process_and_validate(input) { // Fourth ?
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    let len = processed_string.len();
    if len < 10 {
        return Err("Processed string is too short for analysis".into());
