    let third_char = match processed_string.chars().nth(2)
        .ok_or_else(|| "Could not get third character".to_string()) { // Fifth ?
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    };

    if third_char.is_numeric() {
        Ok(len)
    } else {
        Err("Third character is not numeric".into())
    }
}

