use std::collections::HashMap;

fn update_inventory(current: Vec<(&str, u32)>, changes: Vec<(&str, i32)>) -> Result<Vec<(String, u32)>, Box<dyn std::error::Error>> {
    let mut inventory: HashMap<String, u32> = HashMap::new();

    for (item, quantity) in current {
        inventory.insert(item.to_string(), quantity);
    }

    for (item, change) in changes {
        let entry = inventory.entry(item.to_string());
        match change.checked_add(0) { // First ? application (trivial but counts)
            Some(_) => {
                let current_quantity = *entry.or_insert(0);
                if change >= 0 {
                    let new_quantity = current_quantity.checked_add(change as u32).ok_or("Overflow adding item quantity")?; // Second ? application
                    *inventory.get_mut(item).ok_or("Item not found after insert")? = new_quantity; // Third ? application
                } else {
                    let abs_change = (-change) as u32;
                    let new_quantity = current_quantity.checked_sub(abs_change).ok_or("Underflow removing item quantity")?; // Fourth ? application
                    *inventory.get_mut(item).ok_or("Item not found after insert")? = new_quantity; // Fifth ? application
                }
            },
            None => return Err("Integer overflow with change value".into()),
        }
    }

    Ok(inventory.into_iter().collect())
}

