fn fibonacci_sequence(n: u32) -> Result<Vec<u64>, String> {
    if n == 0 {
        return Ok(Vec::new());
    }
    if n == 1 {
        return Ok(vec![0]);
    }

    let mut sequence = Vec::with_capacity(n as usize);
    sequence.push(0);
    sequence.push(1);

    for i in 2..n {
        let a = *sequence.get((i - 2) as usize).ok_or("Index out of bounds for a")?;
        let b = *sequence.get((i - 1) as usize).ok_or("Index out of bounds for b")?;
        let next_fib = a.checked_add(b).ok_or("Overflow during Fibonacci calculation")?;
        sequence.push(next_fib);
    }
    Ok(sequence)
}

fn main() -> Result<(), String> {
    let seq1 = fibonacci_sequence(0)?;
    println!("Fib(0): {:?}", seq1);

    let seq2 = fibonacci_sequence(1)?;
    println!("Fib(1): {:?}", seq2);

    let seq3 = fibonacci_sequence(5)?;
    println!("Fib(5): {:?}", seq3);

    let seq4 = fibonacci_sequence(10)?;
    println!("Fib(10): {:?}", seq4);

    let large_n = 95; // Will cause overflow for u64 around this point
    match fibonacci_sequence(large_n) {
        Ok(seq) => println!("Fib({}): {:?}", large_n, seq),
        Err(e) => println!("Error for Fib({}): {}", large_n, e),
    }

    Ok(())
}

