use std::error::Error;

fn calculate_median_internal(numbers: &mut [f64]) -> Result<f64, Box<dyn Error>> {
    let len = numbers.len();
    if len == 0 {
        return Err("Empty slice".into());
    }

    numbers.sort_by(|a, b| a.partial_cmp(b).ok_or("NaN encountered")?);

    let median = if len % 2 == 1 {
        numbers[len / 2]
    } else {
        let mid1_idx = len / 2 - 1;
        let mid2_idx = len / 2;
        (numbers[mid1_idx] + numbers[mid2_idx]) / 2.0
    };
    Ok(median)
}

fn calculate_median(numbers: &mut [f64]) -> Option<f64> {
    calculate_median_internal(numbers).ok()
}

