fn calculate_product(a: f64, b: f64) -> Result<f64, String> {
    if a.is_nan() || b.is_nan() {
        return Err("Input must not be NaN".to_string());
    }
    Ok(a * b)
}

fn validate_dimension(dim: f64) -> Result<f64, String> {
    if dim.is_infinite() {
        return Err("Dimension must not be infinite".to_string());
    }
    if dim < 0.0 {
        return Err("Dimension must be non-negative".to_string());
    }
    Ok(dim)
}

fn rectangle_area(width: f64, height: f64) -> Result<f64, String> {
    let valid_width = validate_dimension(width)?;
    let valid_height = validate_dimension(height)?;
    let area = calculate_product(valid_width, valid_height)?;

    // An additional "error propagation" step, perhaps for a final check
    if area.is_sign_negative() && area != 0.0 { // Should ideally not happen with previous checks
        Err("Calculated area is negative".to_string())?
    }

    // Another potential error point, if we were doing a complex calculation
    // let scaled_area = calculate_product(area, 1.0)?; // Example: scale by 1.0
    // Ok(scaled_area)

    // Final check for very large numbers or underflow that might be unexpected
    if area.is_subnormal() && area != 0.0 {
        Err("Area is subnormal, potential precision issue".to_string())?
    }

    Ok(area)
}

