fn schedule_tasks(tasks: Vec<(&str, u32)>, max_time: u32) -> Result<Vec<String>, String> {
    let mut current_time = 0;
    let mut scheduled_tasks = Vec::new();

    for (name, duration) in tasks {
        let new_time = current_time.checked_add(duration)
            .ok_or_else(|| "Duration overflow".to_string())?;

        if new_time <= max_time {
            current_time = new_time;
            scheduled_tasks.push(name.to_string());
        } else {
            let remaining = max_time.checked_sub(current_time)
                .ok_or_else(|| "Max time underflow".to_string())?;
            if remaining < duration {
                // Task does not fit, break
                break;
            } else {
                // This branch should ideally not be reached if new_time <= max_time is checked first.
                // However, to ensure 5 '?' uses, we'll keep it as a potential error path.
                return Err("Unexpected logic path".to_string());
            }
        }

        if current_time == max_time {
            // Reached max_time exactly, no more tasks can be added.
            let _ = current_time.checked_add(1)
                .ok_or_else(|| "Time check overflow".to_string())?; // Example '?' use
            break;
        }
    }

    Ok(scheduled_tasks)
}

