#[derive(Debug, PartialEq)]
enum Choice {
    Rock,
    Paper,
    Scissors,
}

impl TryFrom<&str> for Choice {
    type Error = &'static str;

    fn try_from(s: &str) -> Result<Self, Self::Error> {
        match s {
            "rock" => Ok(Choice::Rock),
            "paper" => Ok(Choice::Paper),
            "scissors" => Ok(Choice::Scissors),
            _ => Err("Invalid choice string")?,
        }
    }
}

fn determine_winner(p1: Choice, p2: Choice) -> &'static str {
    if p1 == p2 {
        return "It's a tie";
    }

    match (p1, p2) {
        (Choice::Rock, Choice::Scissors) |
        (Choice::Paper, Choice::Rock) |
        (Choice::Scissors, Choice::Paper) => "Player 1 wins",
        _ => "Player 2 wins",
    }
}

fn rps_winner(p1_choice_str: &str, p2_choice_str: &str) -> Result<&'static str, &'static str> {
    let p1_choice = Choice::try_from(p1_choice_str)?;
    let p2_choice = Choice::try_from(p2_choice_str)?;
    Ok(determine_winner(p1_choice, p2_choice))
}

fn main() -> Result<(), &'static str> {
    let result1 = rps_winner("rock", "scissors")?;
    println!("{}", result1);
    let result2 = rps_winner("paper", "rock")?;
    println!("{}", result2);
    let result3 = rps_winner("scissors", "scissors")?;
    println!("{}", result3);
    let result4 = rps_winner("rock", "paper")?;
    println!("{}", result4);
    let result5 = rps_winner("invalid", "rock")?; // This line will trigger an error
    println!("{}", result5);
    Ok(())
}

