use std::collections::HashMap;
use std::io::{self, BufRead};

fn parse_url_params(query_string: &str) -> Result<HashMap<String, String>, io::Error> {
    let mut params = HashMap::new();
    if query_string.is_empty() {
        return Ok(params);
    }

    let mut reader = io::Cursor::new(query_string);
    let mut buffer = String::new();
    reader.read_to_string(&mut buffer)?; 

    for pair_str in buffer.split('&') {
        if pair_str.is_empty() {
            continue;
        }
        let parts: Vec<&str> = pair_str.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "Malformed key-value pair"));
        }
        let key = parts[0].to_string();
        let value = parts[1].to_string();
        params.insert(key, value);
    }
    Ok(params)
}

fn main() -> Result<(), io::Error> {
    let url_params = parse_url_params("name=Alice&age=30")?;
    println!("{:?}", url_params);

    let empty_params = parse_url_params("")?;
    println!("{:?}", empty_params);

    let single_param = parse_url_params("city=NewYork")?;
    println!("{:?}", single_param);

    let malformed_params = parse_url_params("key1=value1&key2")?; 
    println!("{:?}", malformed_params); // This line will not be reached due to error propagation

    Ok(())
}

