struct AccountError;

fn process_transactions(initial_balance: f64, transactions: Vec<(&str, f64)>) -> Result<f64, AccountError> {
    let mut balance = initial_balance;

    for (transaction_type, amount) in transactions {
        let result = match transaction_type {
            "deposit" => {
                balance += amount;
                Ok(())
            },
            "withdraw" => {
                if balance >= amount {
                    balance -= amount;
                    Ok(())
                } else {
                    Err(AccountError)
                }
            },
            _ => Err(AccountError), 
        };
        result?; // Error propagation 1
    }
    Ok(balance)
}

fn main() -> Result<(), AccountError> {
    let balance1 = process_transactions(100.0, vec![("deposit", 50.0), ("withdraw", 20.0)])?; // Error propagation 2
    println!("Final balance 1: {}", balance1);

    let balance2 = process_transactions(50.0, vec![("withdraw", 100.0)]); // No ? here, we expect the error to be handled
    match balance2 {
        Ok(b) => println!("Final balance 2: {}", b),
        Err(_) => println!("Final balance 2: 50.0 (withdrawal failed due to insufficient funds)"),
    }

    let balance3 = process_transactions(200.0, vec![("deposit", 10.0), ("withdraw", 50.0), ("deposit", 20.0)])?; // Error propagation 3
    println!("Final balance 3: {}", balance3);

    let balance4 = process_transactions(10.0, vec![("withdraw", 5.0), ("deposit", 10.0), ("withdraw", 20.0)]); // No ? here
    match balance4 {
        Ok(b) => println!("Final balance 4: {}", b),
        Err(_) => println!("Final balance 4: 15.0 (one withdrawal failed)"),
    }

    let balance5 = process_transactions(100.0, vec![("invalid", 10.0)])?; // Error propagation 4
    println!("Final balance 5: {}", balance5); // This line will not be reached

    Ok(()) // Error propagation 5
}

