fn calculate_std_dev(numbers: &[f64]) -> Option<f64> {
    if numbers.len() < 2 {
        return None;
    }

    let n = numbers.len() as f64;

    let sum_of_numbers: f64 = numbers.iter().sum();
    let mean = sum_of_numbers / n;

    let mut sum_of_squares_diff = 0.0;
    for &num in numbers.iter() {
        let diff = num - mean;
        sum_of_squares_diff += diff * diff;
    }

    let variance = sum_of_squares_diff / (n - 1.0);
    let std_dev = variance.sqrt();

    Some(std_dev)
}

fn calculate_mean_and_variance(numbers: &[f64]) -> Option<(f64, f64)> {
    let n = numbers.len() as f64;
    if n < 2.0 {
        return None;
    }

    let sum_of_numbers = numbers.iter().try_fold(0.0, |acc, &x| Some(acc + x))?;
    let mean = sum_of_numbers / n;

    let sum_of_squares_diff = numbers.iter().try_fold(0.0, |acc, &x| {
        let diff = x - mean;
        Some(acc + diff * diff)
    })?;

    let variance = sum_of_squares_diff / (n - 1.0);
    Some((mean, variance))
}

