fn sum_digits(mut n: u32) -> u32 {
    let mut sum = 0;
    loop {
        if n == 0 {
            break;
        }
        sum += n % 10;
        n /= 10;
    }
    sum
}

fn sum_digits_with_error_propagation(n: u32) -> Result<u32, std::num::ParseIntError> {
    let s = n.to_string();
    let mut total_sum = 0;
    for c in s.chars() {
        let digit: u32 = c.to_string().parse()?; // ? #1
        total_sum += digit;
    }
    Ok(total_sum)
}

fn process_input_string(input: &str) -> Result<u32, Box<dyn std::error::Error>> {
    let parsed_n: u32 = input.trim().parse()?; // ? #2
    let sum = sum_digits_with_error_propagation(parsed_n)?; // ? #3
    Ok(sum)
}

fn read_and_sum_from_file(path: &str) -> Result<u32, Box<dyn std::error::Error>> {
    let contents = std::fs::read_to_string(path)?; // ? #4
    let first_line = contents.lines().next().ok_or("Empty file")?;
    let sum = process_input_string(first_line)?; // ? #5
    Ok(sum)
}

