fn sum_digits(mut n: u32) -> u32 {
    let mut sum = 0;
    loop {
        if n == 0 {
            break;
        }
        sum += n % 10;
        n /= 10;
    }
    sum
}

fn sum_digits_with_error_propagation(n: u32) -> Result<u32, std::num::ParseIntError> {
    let s = n.to_string();
    let mut total_sum = 0;
    for c in s.chars() {
        let digit: u32 = match c.to_string().parse() {
            Ok(v) => v,
            Err(e) => return Err(e.into()),
        }; // ? #1
        total_sum += digit;
    }
    Ok(total_sum)
}

fn process_input_string(input: &str) -> Result<u32, Box<dyn std::error::Error>> {
    let parsed_n: u32 = match input.trim().parse() {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? #2
    let sum = match sum_digits_with_error_propagation(parsed_n) {
        Ok(v) => v,
        Err(e) => return Err(e.into()),
    }; // ? #3
    Ok(sum)
}

