fn roman_to_int(roman: &str) -> Result<u32, &'static str> {
    let mut total = 0;
    let mut prev_value = 0;

    for c in roman.chars().rev() {
        let current_value = match c {
            'I' => 1,
            'V' => 5,
            'X' => 10,
            'L' => 50,
