            _ => return Err("Invalid Roman numeral character"),
        };

        if current_value < prev_value {
            total = total.checked_sub(current_value).ok_or("Integer underflow")?;
        } else {
            total = total.checked_add(current_value).ok_or("Integer overflow")?;
        }
        prev_value = current_value;
    }
    Ok(total)
}

