fn merge_sorted_vectors(v1: Vec<i32>, v2: Vec<i32>) -> Result<Vec<i32>, &'static str> {
    let mut merged = Vec::with_capacity(v1.len() + v2.len());
    let mut i = 0;
    let mut j = 0;

    while i < v1.len() && j < v2.len() {
        if v1[i] <= v2[j] {
            merged.push(v1[i]);
            i += 1;
        } else {
            merged.push(v2[j]);
            j += 1;
        }
    }

    if i < v1.len() {
        merged.extend_from_slice(&v1[i..]);
    }
    if j < v2.len() {
        merged.extend_from_slice(&v2[j..]);
    }

    // Example of a conditional error propagation, though not strictly needed here for valid input
    if merged.is_empty() && (!v1.is_empty() || !v2.is_empty()) {
        return Err("Merge resulted in empty vector despite non-empty inputs");
    }

    Ok(merged)
}

fn main() -> Result<(), &'static str> {
    let v1 = vec![1, 3, 5];
    let v2 = vec![2, 4, 6];
    let result1 = merge_sorted_vectors(v1, v2)?;
    println!("{:?}", result1);

    let v3 = vec![10];
    let v4 = vec![1, 2];
    let result2 = merge_sorted_vectors(v3, v4)?;
