fn convert_length(value: f64, from_unit: &str, to_unit: &str) -> Result<f64, String> {
    let meters = match from_unit {
        "m" => value,
        "cm" => value / 100.0,
        "km" => value * 1000.0,
        _ => return Err(format!("Unsupported from_unit: {}", from_unit)),
    };

    let result = match to_unit {
        "m" => meters,
        "cm" => meters * 100.0,
        "km" => meters / 1000.0,
        _ => return Err(format!("Unsupported to_unit: {}", to_unit)),
    };
    Ok(result)
}

fn main() -> Result<(), String> {
    let result1 = convert_length(100.0, "cm", "m")?;
    println!("100 cm to m: {}", result1);

    let result2 = convert_length(2.0, "km", "m")?;
    println!("2 km to m: {}", result2);

    let result3 = convert_length(500.0, "m", "km")?;
    println!("500 m to km: {}", result3);

    let result4 = convert_length(1.0, "m", "cm")?;
    println!("1 m to cm: {}", result4);

    let result5 = convert_length(1.0, "cm", "km")?;
    println!("1 cm to km: {}", result5);
    Ok(())
}

